#!/bin/sh
set -ex

AWS_CI_SECRET_ID="/${G_APPLICATION_ID}/dev/cicd/envs"
SECRET_JSON=$(aws secretsmanager get-secret-value \
  --secret-id "$AWS_CI_SECRET_ID" \
  --profile "$G_AWS_PROFILE" \
  --query 'SecretString' \
  --output text)

AWS_ECR_REPO_URL=$(echo "$SECRET_JSON" | jq -r '.AWS_ECR_REPO_URL // empty')
AWS_FE_BUCKET_NAME=$(echo "$SECRET_JSON" | jq -r '.AWS_FE_BUCKET_NAME // empty')
AWS_FE_BUCKET_ARN=$(echo "$SECRET_JSON" | jq -r '.AWS_FE_BUCKET_ARN // empty')
AWS_FE_CLOUDFRONT_DISTRIBUTION_ID=$(echo "$SECRET_JSON" | jq -r '.AWS_FE_CLOUDFRONT_DISTRIBUTION_ID // empty')
AWS_FE_CLOUDFRONT_DOMAIN_NAME=$(echo "$SECRET_JSON" | jq -r '.AWS_FE_CLOUDFRONT_DOMAIN_NAME // empty')
AWS_BE_LAMBDA_MAIN_NAME=$(echo "$SECRET_JSON" | jq -r '.AWS_BE_LAMBDA_MAIN_NAME // empty')
AWS_BE_LAMBDA_MIGRATIONS_NAME=$(echo "$SECRET_JSON" | jq -r '.AWS_BE_LAMBDA_MIGRATIONS_NAME // empty')
AWS_BE_APIGW_ENDPOINT=$(echo "$SECRET_JSON" | jq -r '.AWS_BE_APIGW_ENDPOINT // empty')
AWS_COGNITO_USER_POOL_ID=$(echo "$SECRET_JSON" | jq -r '.AWS_COGNITO_USER_POOL_ID // empty')
AWS_COGNITO_CLIENT_ID=$(echo "$SECRET_JSON" | jq -r '.AWS_COGNITO_CLIENT_ID // empty')
AWS_COGNITO_DOMAIN=$(echo "$SECRET_JSON" | jq -r '.AWS_COGNITO_DOMAIN // empty')

cat << EOF > $GITHUB_WORKSPACE/build.env
AWS_ECR_REPO_URL=$AWS_ECR_REPO_URL
AWS_FE_BUCKET_NAME=$AWS_FE_BUCKET_NAME
AWS_FE_BUCKET_ARN=$AWS_FE_BUCKET_ARN
AWS_FE_CLOUDFRONT_DISTRIBUTION_ID=$AWS_FE_CLOUDFRONT_DISTRIBUTION_ID
AWS_FE_CLOUDFRONT_DOMAIN_NAME=$AWS_FE_CLOUDFRONT_DOMAIN_NAME
AWS_BE_LAMBDA_MAIN_NAME=$AWS_BE_LAMBDA_MAIN_NAME
AWS_BE_LAMBDA_MIGRATIONS_NAME=$AWS_BE_LAMBDA_MIGRATIONS_NAME
AWS_BE_APIGW_ENDPOINT=$AWS_BE_APIGW_ENDPOINT
AWS_COGNITO_USER_POOL_ID=$AWS_COGNITO_USER_POOL_ID
AWS_COGNITO_CLIENT_ID=$AWS_COGNITO_CLIENT_ID
VITE_AWS_USER_POOL_ID=$AWS_COGNITO_USER_POOL_ID
VITE_AWS_USER_POOL_WEB_CLIENT_ID=$AWS_COGNITO_CLIENT_ID
VITE_COGNITO_DOMAIN=$AWS_COGNITO_DOMAIN
VITE_AWS_REGION=$AWS_DEFAULT_REGION
EOF
